import math
import re

DOCS = {
    "Krakatoa":        "The volcano island of Krakatoa erupted with a blast heard thousands of miles away, and the eruption reshaped the entire island.",
    "Reef life":       "A coral reef teems with fish, anemones and slow-growing coral colonies that build limestone over centuries in warm shallow water.",
    "Sahara winds":    "Hot desert wind lifts sand from the Sahara and carries fine dust across the ocean, feeding distant rainforest soils.",
    "Iceland":         "Iceland is a volcanic island where glaciers sit beside active volcano systems, and eruptions can melt glacial ice into floods.",
    "Alpine glaciers": "A glacier grinds slowly down the alpine valley, carving rock and leaving moraines as the ice retreats each summer.",
    "Pacific atolls":  "An atoll forms when a volcanic island sinks below the sea, leaving a ring of coral reef around a calm lagoon.",
    "Monsoon":         "The monsoon wind reverses with the seasons, bringing months of heavy rain that flood rivers and fill reservoirs.",
    "Sea ice":         "Polar sea ice grows in winter darkness and shrinks each summer, and its bright surface reflects sunlight back into space.",
    "Dune fields":     "Wind builds desert dunes grain by grain, and the largest dune fields sing with a low hum as sand avalanches down their faces.",
    "Hotspot chains":  "A volcanic hotspot stays put while the plate drifts over it, stamping out a chain of islands like Hawaii, oldest at one end.",
    "Rainforest":      "A tropical rainforest recycles its own rain: trees pump water skyward, clouds form, and the forest waters itself.",
    "Tsunami":         "An undersea earthquake or a collapsing volcano can push a tsunami across the ocean at the speed of a jet aircraft.",
}

def tokenize(text):
    return re.findall(r"[a-z]+", text.lower())

# Document frequency: in how many docs does each word appear?
doc_tokens = {title: tokenize(text) for title, text in DOCS.items()}
df = {}
for tokens in doc_tokens.values():
    for w in set(tokens):
        df[w] = df.get(w, 0) + 1

N = len(DOCS)
def idf(w):
    return math.log(N / df[w]) if w in df else 0.0

# TF-IDF vector per document (sparse dicts), pre-normalised.
def vectorize(tokens):
    tf = {}
    for w in tokens:
        tf[w] = tf.get(w, 0) + 1
    vec = {w: (count / len(tokens)) * idf(w) for w, count in tf.items()}
    norm = math.sqrt(sum(v * v for v in vec.values())) or 1.0
    return {w: v / norm for w, v in vec.items()}

doc_vecs = {title: vectorize(tokens) for title, tokens in doc_tokens.items()}

def search(query, top=5):
    qvec = vectorize(tokenize(query))
    scored = []
    for title, dvec in doc_vecs.items():
        score = sum(qvec.get(w, 0) * dvec.get(w, 0) for w in qvec)
        if score > 0:
            scored.append((score, title))
    scored.sort(reverse=True)
    return scored[:top]

query = nb.get("query") or "volcano island"
results = search(query)

print(f'query: "{query}"')
if not results:
    print("no matches - every query word is either absent or in every document")
for score, title in results:
    print(f"  {score:.3f}  {title}")

nb["search_results"] = [
    {"title": t, "score": round(s, 3), "snippet": DOCS[t][:110] + "..."}
    for s, t in results
]
nb["search_query_echo"] = query
